//! Typed access to the members of a command object.
//!
//! The getters implement the protocol's value rules: `null` counts as absent
//! and a present member of the wrong type or outside its range is an
//! `InvalidParameterValue`.

use serde_json::{Map, Value};

use crate::error::{Code, Error, Result};

pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    /// Fails with `MissingParameter` for the first absent name.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| !self.is_present(name)) {
            Some(name) => Err(Error::new(
                Code::MissingParameter,
                format!("{name} is required"),
            )),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|value| {
                value
                    .as_str()
                    .ok_or_else(|| invalid(name, "must be a string"))
            })
            .transpose()
    }

    /// A string of `1..=max_len` characters from `A-Z a-z 0-9 _ -`.
    pub fn id_string(&self, name: &str, max_len: usize) -> Result<Option<&'a str>> {
        let value = self.string(name)?;
        if let Some(text) = value
            && !(1..=max_len).contains(&text.chars().count())
            || value.is_some_and(|text| !text.chars().all(is_id_char))
        {
            return Err(invalid(name, "has a bad length or character"));
        }
        Ok(value)
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|value| {
                value
                    .as_bool()
                    .ok_or_else(|| invalid(name, "must be a boolean"))
            })
            .transpose()
    }

    pub fn integer(&self, name: &str, min: u64, max: u64) -> Result<Option<u64>> {
        self.get(name)
            .map(|value| {
                let number = value
                    .as_number()
                    .filter(|n| n.is_i64() || n.is_u64())
                    .ok_or_else(|| invalid(name, "must be an integer"))?;
                // Integers beyond i64 are out of every range anyway.
                let number = number.as_i64().unwrap_or(i64::MAX);
                u64::try_from(number)
                    .ok()
                    .filter(|n| (min..=max).contains(n))
                    .ok_or_else(|| invalid(name, format!("must be between {min} and {max}")))
            })
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|value| {
                value
                    .as_object()
                    .ok_or_else(|| invalid(name, "must be an object"))
            })
            .transpose()
    }
}

pub fn is_id_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

pub fn invalid(name: &str, problem: impl std::fmt::Display) -> Error {
    Error::new(Code::InvalidParameterValue, format!("{name} {problem}"))
}
