//! One queue: its settings, messages and the indexes that keep every
//! operation cheap even with 100000 messages.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};

use serde_json::{Map, Value, json};

use crate::error::{Code, Error, Result};
use crate::params::{Params, invalid};

pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Settings {
    pub visibility_timeout: u64,
    pub delay_seconds: u64,
    pub retention_seconds: u64,
    pub fifo: bool,
    pub content_based_dedup: bool,
    pub dead_letter: Option<DeadLetter>,
}

/// The attributes named in a request; absent ones are `None`.
#[derive(Debug, Default)]
pub struct AttributePatch {
    pub visibility_timeout: Option<u64>,
    pub delay_seconds: Option<u64>,
    pub retention_seconds: Option<u64>,
    pub fifo: Option<bool>,
    pub content_based_dedup: Option<bool>,
    dead_letter_queue: Option<String>,
    max_receive_count: Option<u64>,
}

impl AttributePatch {
    pub fn parse(attributes: Option<&Map<String, Value>>) -> Result<Self> {
        let Some(attributes) = attributes else {
            return Ok(Self::default());
        };
        const KNOWN: [&str; 7] = [
            "VisibilityTimeout",
            "DelaySeconds",
            "RetentionSeconds",
            "Fifo",
            "ContentBasedDeduplication",
            "DeadLetterQueue",
            "MaxReceiveCount",
        ];
        if let Some((name, _)) = attributes
            .iter()
            .find(|(name, value)| !value.is_null() && !KNOWN.contains(&name.as_str()))
        {
            return Err(invalid(name, "is not a known attribute"));
        }
        let p = Params::new(attributes);
        Ok(Self {
            visibility_timeout: p.integer("VisibilityTimeout", 0, 43_200)?,
            delay_seconds: p.integer("DelaySeconds", 0, 900)?,
            retention_seconds: p.integer("RetentionSeconds", 60, 1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_dedup: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.integer("MaxReceiveCount", 1, 1000)?,
        })
    }

    /// The dead-letter configuration, which must be given whole or not at all.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
                queue: queue.clone(),
                max_receive_count,
            })),
            (None, None) => Ok(None),
            _ => Err(Error::new(
                Code::InvalidParameterValue,
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }

    /// The settings of a new queue: given attributes over the defaults.
    pub fn into_settings(self, dead_letter: Option<DeadLetter>) -> Settings {
        Settings {
            visibility_timeout: self.visibility_timeout.unwrap_or(30),
            delay_seconds: self.delay_seconds.unwrap_or(0),
            retention_seconds: self.retention_seconds.unwrap_or(345_600),
            fifo: self.fifo.unwrap_or(false),
            content_based_dedup: self.content_based_dedup.unwrap_or(false),
            dead_letter,
        }
    }
}

impl Settings {
    pub fn apply(&mut self, patch: &AttributePatch, dead_letter: Option<DeadLetter>) {
        self.visibility_timeout = patch.visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = patch.delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = patch.retention_seconds.unwrap_or(self.retention_seconds);
        self.content_based_dedup = patch
            .content_based_dedup
            .unwrap_or(self.content_based_dedup);
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
    }

    pub fn to_json(&self) -> Value {
        let mut attributes = json!({
            "VisibilityTimeout": self.visibility_timeout,
            "DelaySeconds": self.delay_seconds,
            "RetentionSeconds": self.retention_seconds,
            "Fifo": self.fifo,
            "ContentBasedDeduplication": self.content_based_dedup,
        });
        if let Some(dead_letter) = &self.dead_letter {
            attributes["DeadLetterQueue"] = json!(dead_letter.queue);
            attributes["MaxReceiveCount"] = json!(dead_letter.max_receive_count);
        }
        attributes
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Hidden {
    Delayed,
    InFlight,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Visible,
    Delayed,
    InFlight,
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub group: Option<String>,
    receive_count: u64,
    first_received_at: Option<u64>,
    sequence: Option<u64>,
    /// Not visible while `now < hidden_until`; `hidden` says why.
    hidden_until: u64,
    hidden: Hidden,
    receipt: Option<u64>,
}

impl Message {
    pub fn new(id: u64, body: String, group: Option<String>, now: u64, delay: u64) -> Self {
        Self {
            id,
            body,
            sent_at: now,
            group,
            receive_count: 0,
            first_received_at: None,
            sequence: None,
            hidden_until: now + delay,
            hidden: Hidden::Delayed,
            receipt: None,
        }
    }

    fn state(&self, now: u64) -> State {
        match (now < self.hidden_until, self.hidden) {
            (false, _) => State::Visible,
            (true, Hidden::Delayed) => State::Delayed,
            (true, Hidden::InFlight) => State::InFlight,
        }
    }
}

/// The identity of an accepted message, as reported to the sender.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub id: u64,
    pub sequence: Option<u64>,
}

pub struct Queue {
    pub settings: Settings,
    /// Messages keyed by arrival number, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    /// `(sent_at, arrival)` of every message, to find expired ones fast.
    by_age: BTreeSet<(u64, u64)>,
    /// Latest receipt handle of each delivered message -> its arrival number.
    handles: HashMap<u64, u64>,
    /// Deduplication id -> the message accepted with it and when.
    dedup: HashMap<String, (u64, Accepted)>,
    next_arrival: u64,
    next_sequence: u64,
}

impl Queue {
    pub fn new(settings: Settings) -> Self {
        Self {
            settings,
            messages: BTreeMap::new(),
            by_age: BTreeSet::new(),
            handles: HashMap::new(),
            dedup: HashMap::new(),
            next_arrival: 0,
            next_sequence: 1,
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.messages.is_empty()
    }

    /// Drops every message whose retention has run out.
    pub fn expire(&mut self, now: u64) {
        let retention = self.settings.retention_seconds;
        while let Some(&(sent_at, key)) = self.by_age.first() {
            if now < sent_at + retention {
                break;
            }
            self.remove(key);
        }
    }

    fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        self.by_age.remove(&(message.sent_at, key));
        if let Some(handle) = message.receipt {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    fn insert(&mut self, mut message: Message) -> Accepted {
        message.sequence = self.settings.fifo.then(|| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            sequence
        });
        let accepted = Accepted {
            id: message.id,
            sequence: message.sequence,
        };
        let key = self.next_arrival;
        self.next_arrival += 1;
        self.by_age.insert((message.sent_at, key));
        self.messages.insert(key, message);
        accepted
    }

    /// The original send that `dedup_id` duplicates, if its window is open.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<Accepted> {
        self.dedup
            .get(dedup_id)
            .filter(|(at, _)| now - at < DEDUP_WINDOW)
            .map(|&(_, accepted)| accepted)
    }

    /// Adds a sent message; `dedup_id` is set on FIFO queues.
    pub fn accept(&mut self, message: Message, dedup_id: Option<String>) -> Accepted {
        let sent_at = message.sent_at;
        let accepted = self.insert(message);
        if let Some(dedup_id) = dedup_id {
            self.dedup.insert(dedup_id, (sent_at, accepted));
        }
        accepted
    }

    /// Adds a message moved here from another queue's dead-letter handling.
    pub fn accept_dead_letter(&mut self, mut message: Message, now: u64) {
        message.receive_count = 0;
        message.first_received_at = None;
        message.hidden_until = 0;
        message.receipt = None;
        if now < message.sent_at + self.settings.retention_seconds {
            self.insert(message);
        }
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_age.clear();
        self.handles.clear();
    }

    pub fn counts(&self, now: u64) -> Value {
        let count = |wanted| {
            self.messages
                .values()
                .filter(|m| m.state(now) == wanted)
                .count()
        };
        json!({
            "Visible": count(State::Visible),
            "InFlight": count(State::InFlight),
            "Delayed": count(State::Delayed),
        })
    }

    /// Delivers up to `max` messages. Returns their JSON and the messages
    /// that reached `MaxReceiveCount`, already removed, for the caller to
    /// move to the dead-letter queue.
    pub fn receive(
        &mut self,
        now: u64,
        max: usize,
        visibility_timeout: u64,
        next_handle: &mut u64,
    ) -> (Vec<Value>, Vec<Message>) {
        let max_receive_count = self.settings.dead_letter.as_ref().map(|d| d.max_receive_count);
        let fifo = self.settings.fifo;
        let mut seen_groups: HashSet<String> = HashSet::new();
        let mut delivered = Vec::new();
        let mut dead = Vec::new();
        for (&key, message) in self.messages.iter_mut() {
            if delivered.len() == max {
                break;
            }
            let blocked = message.group.as_ref().is_some_and(|g| seen_groups.contains(g));
            let eligible = !blocked && message.state(now) == State::Visible;
            let dead_letter =
                eligible && max_receive_count.is_some_and(|max| message.receive_count >= max);
            if !dead_letter && let Some(group) = &message.group {
                seen_groups.insert(group.clone());
            }
            if dead_letter {
                dead.push(key);
            } else if eligible {
                if let Some(old) = message.receipt {
                    self.handles.remove(&old);
                }
                let handle = *next_handle;
                *next_handle += 1;
                message.receipt = Some(handle);
                self.handles.insert(handle, key);
                message.receive_count += 1;
                message.first_received_at.get_or_insert(now);
                message.hidden = Hidden::InFlight;
                message.hidden_until = now + visibility_timeout;
                delivered.push(message.delivery_json(handle, fifo));
            }
        }
        let dead = dead.into_iter().filter_map(|key| self.remove(key)).collect();
        (delivered, dead)
    }

    /// The message that `handle` is the latest handle of, if it is in flight.
    fn in_flight(&mut self, handle: u64, now: u64) -> Option<(u64, &mut Message)> {
        let key = *self.handles.get(&handle)?;
        let message = self.messages.get_mut(&key)?;
        (message.state(now) == State::InFlight).then_some((key, message))
    }

    pub fn delete(&mut self, handle: u64, now: u64) -> Result<()> {
        let (key, _) = self.in_flight(handle, now).ok_or_else(expired)?;
        self.remove(key);
        Ok(())
    }

    pub fn change_visibility(&mut self, handle: u64, now: u64, timeout: u64) -> Result<()> {
        let (_, message) = self.in_flight(handle, now).ok_or_else(expired)?;
        message.hidden_until = now + timeout;
        Ok(())
    }
}

fn expired() -> Error {
    Error::new(
        Code::ReceiptHandleExpired,
        "the receipt handle does not belong to a message in flight in this queue",
    )
}

impl Message {
    fn delivery_json(&self, handle: u64, fifo: bool) -> Value {
        let mut json = json!({
            "MessageId": format!("m-{}", self.id),
            "ReceiptHandle": format!("r-{handle}"),
            "Body": self.body,
            "ReceiveCount": self.receive_count,
            "SentAt": self.sent_at,
            "FirstReceivedAt": self.first_received_at,
        });
        if fifo {
            json["GroupId"] = json!(self.group);
            json["SequenceNumber"] = json!(self.sequence);
        }
        json
    }
}
