//! The broker: all queues, the virtual clock, and command dispatch.

use std::collections::HashMap;

use serde_json::{Map, Value, json};

use crate::error::{Code, Error, Result};
use crate::params::Params;
use crate::queue::{AttributePatch, MAX_MESSAGES, Message, Queue};

const MAX_QUEUES: usize = 1000;

pub struct Broker {
    now: u64,
    queues: HashMap<String, Queue>,
    messages_accepted: u64,
    handles_issued: u64,
}

impl Default for Broker {
    fn default() -> Self {
        Self::new()
    }
}

impl Broker {
    pub fn new() -> Self {
        Self {
            now: 0,
            queues: HashMap::new(),
            messages_accepted: 0,
            handles_issued: 0,
        }
    }

    /// Runs one input line (without its newline) and returns the response line.
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.execute(line) {
            Ok(Value::Object(mut result)) => {
                result.insert("ok".into(), Value::Bool(true));
                Value::Object(result)
            }
            Ok(_) => unreachable!("commands return objects"),
            Err(error) => json!({
                "ok": false,
                "error": {"code": error.code.as_str(), "message": error.message},
            }),
        };
        response.to_string()
    }

    fn execute(&mut self, line: &[u8]) -> Result<Value> {
        let bad = |message: &str| Error::new(Code::InvalidRequest, message);
        let text = std::str::from_utf8(line).map_err(|_| bad("line is not valid UTF-8"))?;
        let Ok(Value::Object(members)) = serde_json::from_str(text) else {
            return Err(bad("line is not a JSON object"));
        };
        let Some(Value::String(command)) = members.get("Command") else {
            return Err(bad("Command must be a string"));
        };
        let p = Params::new(&members);
        match command.as_str() {
            "CreateQueue" => self.create_queue(&p),
            "SetQueueAttributes" => self.set_queue_attributes(&p),
            "GetQueueAttributes" => self.get_queue_attributes(&p),
            "ListQueues" => self.list_queues(&p),
            "DeleteQueue" => self.delete_queue(&p),
            "PurgeQueue" => self.purge_queue(&p),
            "Tick" => self.tick(&p),
            "SendMessage" => self.send_message(&p),
            "ReceiveMessage" => self.receive_message(&p),
            "DeleteMessage" => self.delete_message(&p),
            "ChangeMessageVisibility" => self.change_message_visibility(&p),
            _ => Err(bad("unknown command")),
        }
    }

    /// Looks a queue up and applies retention up to the present first.
    fn queue(&mut self, name: &str) -> Result<&mut Queue> {
        let queue = self.queues.get_mut(name).ok_or_else(|| does_not_exist(name))?;
        queue.expire(self.now);
        Ok(queue)
    }

    fn create_queue(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        if !valid_queue_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, "bad queue name"));
        }
        let patch = AttributePatch::parse(p.object("Attributes")?)?;
        let fifo = patch.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                Code::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        if patch.content_based_dedup == Some(true) && !fifo {
            return Err(invalid_value("ContentBasedDeduplication needs a FIFO queue"));
        }
        let dead_letter = patch.dead_letter()?;
        let settings = patch.into_settings(dead_letter);
        if let Some(existing) = self.queues.get(name) {
            return if existing.settings == settings {
                Ok(json!({}))
            } else {
                Err(Error::new(
                    Code::QueueAlreadyExists,
                    "the queue exists with different attributes",
                ))
            };
        }
        if let Some(dead_letter) = &settings.dead_letter {
            let target = self
                .queues
                .get(&dead_letter.queue)
                .ok_or_else(|| does_not_exist(&dead_letter.queue))?;
            if target.settings.fifo != fifo {
                return Err(invalid_value("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(settings));
        Ok(json!({}))
    }

    fn set_queue_attributes(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        let patch = AttributePatch::parse(p.object("Attributes")?)?;
        let now = self.now;
        let fifo = self.queue(name)?.settings.fifo;
        if patch.fifo.is_some() {
            return Err(Error::new(
                Code::UnsupportedOperation,
                "the type of a queue cannot change",
            ));
        }
        if patch.content_based_dedup == Some(true) && !fifo {
            return Err(invalid_value("ContentBasedDeduplication needs a FIFO queue"));
        }
        let dead_letter = patch.dead_letter()?;
        if let Some(dead_letter) = &dead_letter {
            let target = self
                .queues
                .get(&dead_letter.queue)
                .ok_or_else(|| does_not_exist(&dead_letter.queue))?;
            if dead_letter.queue == name || target.settings.fifo != fifo {
                return Err(invalid_value("bad dead-letter queue"));
            }
        }
        let queue = self.queue(name)?;
        queue.settings.apply(&patch, dead_letter);
        // A lower retention takes effect now, before a later raise can undo it.
        queue.expire(now);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        let now = self.now;
        let queue = self.queue(name)?;
        Ok(json!({"Attributes": queue.settings.to_json(), "Counts": queue.counts(now)}))
    }

    fn list_queues(&mut self, p: &Params) -> Result<Value> {
        let prefix = p.string("Prefix")?.unwrap_or_default();
        let mut names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        names.sort();
        Ok(json!({"QueueNames": names}))
    }

    fn delete_queue(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        self.queue(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.settings.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.settings.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn purge_queue(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        self.queue(name)?.purge();
        Ok(json!({}))
    }

    fn tick(&mut self, p: &Params) -> Result<Value> {
        p.require(&["Seconds"])?;
        let seconds = p.integer("Seconds", 0, 1_209_600)?.unwrap_or_default();
        self.now += seconds;
        Ok(json!({"Now": self.now}))
    }

    fn send_message(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName", "Body"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        let body = p.string("Body")?.unwrap_or_default();
        if !(1..=1024).contains(&body.len()) {
            return Err(invalid_value("Body must be 1 to 1024 bytes"));
        }
        let delay = p.integer("DelaySeconds", 0, 900)?;
        let group = p.id_string("GroupId", 128)?;
        let dedup_id = p.id_string("DeduplicationId", 128)?;
        let now = self.now;
        let queue = self.queue(name)?;
        let fifo = queue.settings.fifo;
        if (!fifo && (group.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(
                Code::UnsupportedOperation,
                "parameter not supported by this type of queue",
            ));
        }
        let mut dedup_key = None;
        if fifo {
            if group.is_none() {
                return Err(missing("GroupId"));
            }
            if dedup_id.is_none() && !queue.settings.content_based_dedup {
                return Err(missing("DeduplicationId"));
            }
            let key = dedup_id.unwrap_or(body);
            if let Some(original) = queue.duplicate_of(key, now) {
                return Ok(send_result(original.id, original.sequence));
            }
            dedup_key = Some(key.to_owned());
        }
        if queue.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "the queue is full"));
        }
        self.messages_accepted += 1;
        let delay = delay.unwrap_or(queue.settings.delay_seconds);
        let message = Message::new(
            self.messages_accepted,
            body.to_owned(),
            group.map(str::to_owned),
            now,
            delay,
        );
        let accepted = queue.accept(message, dedup_key);
        Ok(send_result(accepted.id, accepted.sequence))
    }

    fn receive_message(&mut self, p: &Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.string("QueueName")?.unwrap_or_default();
        let max = p.integer("MaxMessages", 1, 10)?.unwrap_or(1);
        let timeout = p.integer("VisibilityTimeout", 0, 43_200)?;
        let now = self.now;
        let queue = self.queue(name)?;
        let timeout = timeout.unwrap_or(queue.settings.visibility_timeout);
