#[test]
fn malformed_lines_are_invalid_requests() {
    let out = run(&["", "[]", r#"{"Command": 1}"#, r#"{"Command": "Nope"}"#]);
    assert!(out.iter().all(|r| code(r) == "InvalidRequest"));
}

#[test]
fn send_receive_delete_round_trip() {
    let out = run(&[
        r#"{"Command":"CreateQueue","QueueName":"q"}"#,
        r#"{"Command":"SendMessage","QueueName":"q","Body":"hi"}"#,
        r#"{"Command":"ReceiveMessage","QueueName":"q"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-1"}"#,
        r#"{"Command":"DeleteMessage","QueueName":"q","ReceiptHandle":"r-01"}"#,
    ]);
    assert_eq!(out[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(
        out[2]["Messages"],
        json!([{"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hi",
                "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}])
    );
    assert_eq!(out[3], json!({"ok": true}));
    assert_eq!(code(&out[4]), "ReceiptHandleExpired");
    assert_eq!(code(&out[5]), "ReceiptHandleInvalid");
}

