        r#"{"Command":"CreateQueue","QueueName":"x.fifo"}"#,
        r#"{"Command":"SendMessage","QueueName":"a b","Body":5}"#,
        r#"{"Command":"SendMessage","QueueName":"a b"}"#,
        r#"{"Command":"SendMessage","QueueName":"a b","Body":"x"}"#,
    ]);
    assert_eq!(code(&out[0]), "QueueNameInvalid");
    assert_eq!(code(&out[1]), "QueueNameInvalid");
    assert_eq!(code(&out[2]), "InvalidParameterValue");
    assert_eq!(code(&out[3]), "MissingParameter");
    assert_eq!(code(&out[4]), "QueueDoesNotExist");
}

#[test]
fn a_full_queue_fills_quickly_and_then_refuses() {
    let mut broker = Broker::new();
    broker.handle_line(br#"{"Command":"CreateQueue","QueueName":"q"}"#);
    for _ in 0..100_000 {
        broker.handle_line(br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    }
    let full = broker.handle_line(br#"{"Command":"SendMessage","QueueName":"q","Body":"x"}"#);
    assert!(full.contains("LimitExceeded"), "{full}");
}

#[test]
fn binary_answers_every_line_including_an_unterminated_last_one() {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(b"{\"Command\":\"Tick\",\"Seconds\":5}\n\n{\"Command\":\"Tick\",\"Seconds\":1}").unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(output.status.success());
    let lines: Vec<Value> = String::from_utf8(output.stdout)
        .unwrap()
        .lines()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect();
    assert_eq!(lines.len(), 3);
    assert_eq!(lines[0]["Now"], 5);
    assert_eq!(code(&lines[1]), "InvalidRequest");
    assert_eq!(lines[2]["Now"], 6);
}
